void Solver::bump_var(int var, double coeff) {
    // increase activity proportionally to the given coefficient
    double inc = var_inc * coeff;
    activity[var] += inc;

    // keep activity values from blowing up – rescale when a limit is exceeded
    const double ACT_LIMIT = 1e120;
    if (activity[var] > ACT_LIMIT) {
        double scale = 1e-120;
        for (int i = 1; i <= vars; ++i) activity[i] *= scale;
        var_inc *= scale;
    }

    // make sure the variable participates in the VSIDS heap
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        vsids.insert(var);
    }
}
